### 1. Drag and Drop de Elementos (Produtos, Categorias e Free Text)

Esta lógica está localizada no arquivo **`components/MenuPreview.tsx`**. Ela utiliza a biblioteca `@dnd-kit`.

**Definição dos Sensores e Handlers (Lógica):**
```typescript
  // DnD Sensors
  // REFACTORED: Strict Mouse vs Touch logic for Mobile Support
  const sensors = useSensors(
    useSensor(MouseSensor, {
        activationConstraint: { distance: 10 } // Desktop: prevents accidental drags on click
    }),
    useSensor(TouchSensor, {
        activationConstraint: { 
            delay: 150, // FAST: Activate before the OS Long Press vibration/menu
            tolerance: 20 // LOOSE: Allow 20px of finger movement/wiggle before cancelling
        } 
    }),
    useSensor(KeyboardSensor, {
      coordinateGetter: sortableKeyboardCoordinates,
    })
  );

  // --- DnD Event Handlers ---
  const handleDragStart = (event: DragStartEvent) => {
    // ... (Define quem está sendo arrastado)
  };

  const handleDragOver = (event: DragOverEvent) => {
    const { active, over } = event;
    if (!over) return;

    const activeType = active.data.current?.type;
    const activeCat = active.data.current?.categoryId;
    const overCat = over.data.current?.categoryId;

    // Constraint Logic
    if (activeType === 'product') {
        const product = products.find(p => p.id === active.id);
        const isFreeText = product?.isFreeText;

        if (!isFreeText) {
            // Strict Product Jail: Must stay in same category
            if (activeCat !== overCat) {
                setIsInvalidMove(true);
            } else {
                setIsInvalidMove(false);
            }
        } else {
            // Free Text is a Joker: Always valid
            setIsInvalidMove(false);
        }
    } else if (activeType === 'category') {
        setIsInvalidMove(false);
    }
  };

  const handleDragEnd = (event: DragEndEvent) => {
    // ... (Lógica completa de reordenação, troca de margens e free text vs products)
  };
```

**Contexto e Renderização (JSX):**
```typescript
<DndContext sensors={sensors} collisionDetection={closestCenter} onDragStart={handleDragStart} onDragOver={handleDragOver} onDragEnd={handleDragEnd}>
    {/* ... Renderização das páginas e itens ... */}
</DndContext>
```

