### 2. Drag and Drop de "Added Images" (Imagem Adicionada)

Esta lógica também está em **`components/MenuPreview.tsx`**, mas não usa o `@dnd-kit`. Ela usa eventos de ponteiro nativos (`onPointerDown`, `pointermove`) para posicionamento absoluto (livre).

**Lógica de Arraste:**
```typescript
  // --- Image Drag Handlers ---

  const handleImageDragStart = (e: React.PointerEvent, imgId: string) => {
      e.preventDefault();
      e.stopPropagation();
      setDraggedImageId(imgId);
      handleSelection('addedImage', imgId);

      const el = e.currentTarget as HTMLElement;
      const startX = e.clientX;
      const startY = e.clientY;
      const rect = el.getBoundingClientRect();
      const parentRect = el.parentElement?.getBoundingClientRect();

      if (!parentRect) return;

      const initialOffX = (rect.left - parentRect.left) / scale;
      const initialOffY = (rect.top - parentRect.top) / scale;

      const handlePointerMove = (moveEvent: PointerEvent) => {
          const deltaX = (moveEvent.clientX - startX) / scale;
          const deltaY = (moveEvent.clientY - startY) / scale;

          if (onStyleUpdate) {
             onStyleUpdate(prev => ({
                 ...prev,
                 addedImages: prev.addedImages?.map(img => {
                     if (img.id === imgId) {
                         return {
                             ...img,
                             x: initialOffX + deltaX,
                             y: initialOffY + deltaY
                         };
                     }
                     return img;
                 }),
                 name: 'Custom'
             }));
          }
      };

      const handlePointerUp = () => {
          window.removeEventListener('pointermove', handlePointerMove);
          window.removeEventListener('pointerup', handlePointerUp);
          setDraggedImageId(null);
      };

      window.addEventListener('pointermove', handlePointerMove);
      window.addEventListener('pointerup', handlePointerUp);
  };
```

