const handleDragStart = (e: React.DragEvent, type: 'category' | 'product', id: string, group?: string, index?: number) => {
    if (editingId) {
        e.preventDefault();
        return;
    }
    e.stopPropagation();
    isDraggingRef.current = true;
    wasDroppedRef.current = false;
    setDraggedItem({ type, id, group, index });

    if (type === 'category') {
      updateLiveCategoryOrder([...sortedCategories]);
    }

    e.dataTransfer.effectAllowed = 'move';
    e.dataTransfer.setData('text/plain', id); 
    // Set a transparent drag image so we can handle custom rendering
    const img = new Image();
    img.src = 'data:image/gif;base64,R0lGODlhAQABAIAAAAAAAP///yH5BAEAAAAALAAAAAABAAEAAAIBRAA7'; 
    e.dataTransfer.setDragImage(img, 0, 0);
};

const handleDragOver = useCallback((e: React.DragEvent, targetId: string, targetType: 'category' | 'product', targetGroup?: string) => {
    e.preventDefault(); 
    e.stopPropagation();

    if (!draggedItem) return;

    // Logic to ensure we don't drop products into categories incorrectly
    let effectiveTargetType = targetType;
    let effectiveTargetId = targetId;

    if (draggedItem.type === 'category' && targetType === 'product') {
        if (!targetGroup) return;
        effectiveTargetType = 'category';
        effectiveTargetId = targetGroup; 
    }

    if (draggedItem.type !== effectiveTargetType) {
        e.dataTransfer.dropEffect = 'none';
        return;
    }

    // Main Sorting Logic
    if (draggedItem.type === 'category' && effectiveTargetType === 'category') {
        const currentOrder = liveCategoryOrderRef.current || sortedCategories;
        const dragIdx = currentOrder.indexOf(draggedItem.id);
        const targetIdx = currentOrder.indexOf(effectiveTargetId);

        // Swap items in the live array
        if (dragIdx !== -1 && targetIdx !== -1 && dragIdx !== targetIdx) {
            const newOrder = [...currentOrder];
            newOrder.splice(dragIdx, 1);
            newOrder.splice(targetIdx, 0, draggedItem.id);
            updateLiveCategoryOrder(newOrder);
        }
    } else if (draggedItem.type === 'product' && targetType === 'product') {
        // Similar logic for products within a category
        const groupName = draggedItem.group!;
        const currentOrder = liveProductOrderRef.current?.[groupName] || groupedProducts[groupName]?.map(p => p.id) || [];
        const dragIdx = currentOrder.indexOf(draggedItem.id);
        const targetIdx = currentOrder.indexOf(targetId);

        if (dragIdx !== -1 && targetIdx !== -1 && dragIdx !== targetIdx) {
            const newOrder = [...currentOrder];
            newOrder.splice(dragIdx, 1);
            newOrder.splice(targetIdx, 0, draggedItem.id);
            const prevLiveOrder = liveProductOrderRef.current || {};
            updateLiveProductOrder({ ...prevLiveOrder, [groupName]: newOrder });
        }
    }
    setDropTarget(null); 
}, [draggedItem, sortedCategories, groupedProducts, isInvalidDrop]);

